Object.assign(window.DYLEAN_DATA.files["Library/Init/Data/RArray.lean"],{"text":"/-\nCopyright (c) 2024 Lean FRO, LLC. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: Joachim Breitner\n-/\n\nmodule\n\nprelude\npublic import Init.GetElem\nimport Init.PropLemmas\n\npublic section\n\n@[expose] section\n\nnamespace Lean\n\n/--\nA `RArray` can model `Fin n → α` or `Array α`, but is optimized for a fast kernel-reducible `get`\noperation.\n\nThe primary intended use case is the “denote” function of a typical proof by reflection proof, where\nonly the `get` operation is necessary. It is not suitable as a general-purpose data structure.\n\nThere is no well-formedness invariant attached to this data structure, to keep it concise; it's\nsemantics is given through `RArray.get`. In that way one can also view an `RArray` as a decision\ntree implementing `Nat → α`.\n\nSee `RArray.ofFn` and `RArray.ofArray` in module `Lean.Data.RArray` for functions that construct an\n`RArray`.\n-/\ninductive RArray (α : Type u) : Type u where\n  | leaf : α → RArray α\n  | branch : Nat → RArray α → RArray α → RArray α\n\nvariable {α : Type u}\n\n/-- The crucial operation, written with very little abstractional overhead -/\nnoncomputable abbrev RArray.get (a : RArray α) (n : Nat) : α :=\n  RArray.rec (fun x => x) (fun p _ _ l r => (Nat.ble p n).rec l r) a\n\nprivate theorem RArray.get_eq_def (a : RArray α) (n : Nat) :\n  a.get n = match a with\n    | .leaf x => x\n    | .branch p l r => (Nat.ble p n).rec (l.get n) (r.get n) := by\n  conv => lhs; unfold RArray.get\n  split <;> rfl\n\n/-- `RArray.get`, implemented conventionally -/\ndef RArray.getImpl (a : RArray α) (n : Nat) : α :=\n  match a with\n  | .leaf x => x\n  | .branch p l r => if n < p then l.getImpl n else r.getImpl n\n\n@[csimp]\ntheorem RArray.get_eq_getImpl : @RArray.get = @RArray.getImpl := by\n  funext α a n\n  induction a with\n  | leaf _ => rfl\n  | branch p l r ihl ihr =>\n    rw [RArray.getImpl, RArray.get_eq_def]\n    simp only [ihl, ihr, ← Nat.not_le, ← Nat.ble_eq, ite_not]\n    cases hnp : Nat.ble p n <;> rfl\n\ninstance : GetElem (RArray α) Nat α (fun _ _ => True) where\n  getElem a n _ := a.get n\n\ndef RArray.size : RArray α → Nat\n  | leaf _ => 1\n  | branch _ l r => l.size + r.size\n\nend Lean\n","refs":[[32,10,32,16,"a84c77bec64e",true],[33,15,33,21,"a84c77bec64e",false],[34,13,34,16,"1a9353d78c15",false],[34,19,34,25,"a84c77bec64e",false],[34,30,34,36,"a84c77bec64e",false],[34,41,34,47,"a84c77bec64e",false],[39,21,39,31,"1c01ae307b54",true],[39,37,39,43,"a84c77bec64e",false],[39,52,39,55,"1a9353d78c15",false],[40,2,40,12,"2e69f0e73ebc",false],[40,45,40,52,"bbffcfebf3f2",false],[40,58,40,61,"9578be1778d9",false],[42,39,42,45,"a84c77bec64e",false],[42,54,42,57,"1a9353d78c15",false],[43,4,43,7,"1c01ae307b54",false],[44,6,44,11,"e358208363ad",false],[45,6,45,13,"2a7dbc03eb74",false],[45,24,45,31,"bbffcfebf3f2",false],[45,37,45,40,"9578be1778d9",false],[45,44,45,47,"1c01ae307b54",false],[45,54,45,57,"1c01ae307b54",false],[46,22,46,32,"1c01ae307b54",false],[50,24,50,30,"a84c77bec64e",false],[50,39,50,42,"1a9353d78c15",false],[52,4,52,9,"e358208363ad",false],[53,4,53,11,"2a7dbc03eb74",false],[56,32,56,43,"1c01ae307b54",false],[56,33,56,43,"1c01ae307b54",false],[59,4,59,8,"e358208363ad",false],[60,4,60,10,"2a7dbc03eb74",false],[62,27,62,37,"c054591e46c1",false],[62,41,62,51,"e953d5584324",false],[62,53,62,60,"c08a56855970",false],[63,16,63,23,"bbffcfebf3f2",false],[65,11,65,18,"8364d268f15d",false],[65,20,65,26,"a84c77bec64e",false],[65,30,65,33,"1a9353d78c15",false],[65,48,65,52,"84a43b20b979",false],[66,2,66,9,"8afa50b498ad",false],[66,21,66,24,"1c01ae307b54",false],[68,18,68,24,"a84c77bec64e",false],[68,29,68,32,"1a9353d78c15",false],[69,4,69,8,"e358208363ad",false],[70,4,70,10,"2a7dbc03eb74",false]]});
